ext('c12_eng_ch15',[
C("🍂","कविता की पृष्ठभूमि",["कवि: जॉन कीट्स","रचना: 1819","विषय: शरद ऋतु","शैली: ओड (श्रद्धा-गीत)"],"ओड टू ऑटम अंग्रेज़ी के रोमांटिक कवि जॉन कीट्स ने अठारह सौ उन्नीस में लिखी। ओड एक ऐसी कविता होती है जिसमें किसी व्यक्ति, वस्तु या ऋतु की प्रशंसा श्रद्धा के साथ की जाती है। यहाँ कवि ने शरद ऋतु को एक जीवित पात्र की तरह संबोधित किया है। कीट्स ने यह कविता इंग्लैंड के विंचेस्टर में टहलते हुए खेतों की सुंदरता देखकर लिखी थी। वह अपने जीवन के बहुत कठिन दौर में भी इस ऋतु की शांति से बहुत प्रभावित हुए थे।"),
Q("ओड किसे कहते हैं?","किसी व्यक्ति, वस्तु या ऋतु की प्रशंसा में लिखी गंभीर और भावपूर्ण कविता","अपने शब्दों में सोचिए... ओड एक प्रशंसा-गीत है। इसमें कवि किसी चीज़ को सम्मान से संबोधित करता है और उसके गुण गिनाता है। यहाँ वह चीज़ शरद ऋतु है। इसलिए उत्तर है, किसी की प्रशंसा में लिखी भावपूर्ण कविता।"),
C("🌾","पहले पद का भाव",["शरद: कुहासे और पके फलों की ऋतु","सूर्य का साथ","बेलें फलों से लदी","सेब, फल और अनाज पकते हैं"],"पहले पद में कवि शरद को कुहासे की और फल पकने की ऋतु कहते हैं। वह सूर्य की सहेली भी है, जो मिलकर फसलों को पकाती है। बेलें अंगूर से लद जाती हैं, पेड़ों पर सेब झुक जाते हैं और फल अंदर तक पक जाते हैं। मेवों के भीतर मीठा गूदा भर जाता है। फूल देर तक खिलते रहते हैं, ताकि मधुमक्खियाँ समझें कि गर्मी कभी ख़त्म नहीं होगी। यह पद भरपूर पैदावार और प्रचुरता का चित्र है।"),
Q("पहले पद में शरद को सूर्य की सहेली क्यों कहा गया है?","क्योंकि दोनों मिलकर फल और फ़सल पकाते हैं","सोचिए... सूरज की गर्मी और शरद की नमी मिलकर फलों को पकाते हैं। जैसे दो दोस्त मिलकर काम करें। इसलिए कवि ने शरद को सूर्य की गहरी मित्र कहा है, जो फ़सल पकाने में साथ देती है।"),
C("🌬️","दूसरे पद का भाव",["शरद का मानवीकरण","खलिहान में बैठी किसान महिला","खेत में सोई थकी कटाई वाली","नदी पार करती गवेषक"],"दूसरे पद में कवि शरद को अलग-अलग रूपों में एक इंसान की तरह दिखाते हैं। कभी वह खलिहान में अनाज फटकती स्त्री है, जिसके बाल हवा में उड़ रहे हैं। कभी वह खेत में आधी कटी फ़सल के पास थककर सोई कटाई करने वाली है, जिसे अफ़ीम की ख़ुशबू ने सुला दिया। कभी वह सिर पर बोझ लेकर नदी पार करती दिखती है। यहाँ कवि ने मेहनत और विश्राम दोनों के चित्र दिए हैं।"),
Q("मानवीकरण अलंकार क्या है? इस कविता से उदाहरण दीजिए।","निर्जीव वस्तु को मनुष्य की तरह दिखाना; शरद को स्त्री के रूप में दिखाया गया है","पहचानिए... जब निर्जीव या प्रकृति की चीज़ को इंसान की तरह काम करता दिखाया जाए, तो वह मानवीकरण है। यहाँ शरद ऋतु कभी अनाज फटकती है, कभी सोती है, कभी नदी पार करती है। यह साफ़ मानवीकरण है।"),
C("🎶","तीसरे पद का भाव",["वसंत के गीत कहाँ?","शरद का अपना संगीत","मच्छरों की गुंजार","चिड़ियाँ, भेड़ें और झींगुर"],"तीसरे पद में कवि पूछता है कि वसंत के गीत कहाँ गए। फिर ख़ुद ही जवाब देता है कि शरद का भी अपना संगीत है। शाम के समय मच्छरों की हल्की गुंजार सुनाई देती है, भेड़ों की मिमियाहट आती है, झींगुर गाते हैं, और दूर से पक्षी चहकते हैं। ये आवाज़ें उदास नहीं हैं, बल्कि दिन ढलने की शांति और संतोष को बताती हैं।"),
Q("कवि ने शरद के संगीत में कौन-सी आवाज़ें गिनाई हैं?","मच्छरों की गुंजार, भेड़ों की मिमियाहट, झींगुर और पक्षियों का स्वर","याद कीजिए... इस पद में कवि सूर्यास्त के समय की आवाज़ें बताता है, यानी मच्छरों की गुंजार, भेड़ों का मिमियाना, झींगुरों का गाना और पक्षियों की चहचहाहट। इनसे शाम की शांति महसूस होती है।"),
C("🎨","बिंब और भाषा",["दृश्य बिंब","स्पर्श और गंध","श्रव्य बिंब","मानवीकरण"],"कीट्स की भाषा में कई इंद्रियों के चित्र मिलते हैं। आँखों के लिए पके फल और सुनहरा खेत। स्पर्श के लिए पके अंदर तक भरे फल की भरपूरता। गंध के लिए अफ़ीम के फूलों की ख़ुशबू। और कानों के लिए झींगुर और पक्षियों की ध्वनि। इन्हें बिंब कहते हैं। कवि का मानवीकरण भी बहुत सुंदर है। भाषा सरल, मीठी और प्रवाहमय है, इसलिए कविता पढ़ते समय एक चित्र आँखों के सामने बन जाता है।"),
Q("दृश्य बिंब और श्रव्य बिंब का एक-एक उदाहरण दीजिए।","दृश्य: पके फल/सुनहरे खेत; श्रव्य: झींगुर का गाना/मच्छरों की गुंजार","इंद्रिय के आधार पर सोचिए... आँखों से जो दिखे, जैसे सुनहरी फ़सल और फलों से लदे पेड़, वह दृश्य बिंब है। कानों से जो सुनाई दे, जैसे झींगुर की आवाज़ और पक्षियों की चहचहाहट, वह श्रव्य बिंब है।"),
C("💭","कविता का केंद्रीय भाव",["परिवर्तन स्वाभाविक","हर ऋतु का सौंदर्य","पूर्णता और संतोष","जीवन-मृत्यु का मेल"],"इस कविता का केंद्रीय भाव यह है कि हर ऋतु अपनी जगह सुंदर होती है। वसंत की ताज़गी की तरह शरद की परिपक्वता भी सुंदर है। कवि जानता है कि शरद के बाद सर्दी आएगी और जीवन का अंत भी, पर वह दुखी नहीं है। वह शरद की पूर्णता और संतोष को स्वीकार करता है। यानी जीवन के हर चरण का अपना आनंद है और बदलाव को सहज मानकर अपनाना चाहिए।"),
Q("कविता से हमें क्या सीख मिलती है?","परिवर्तन को सहज स्वीकार करो और हर समय का सौंदर्य देखो","सोचिए... शरद के बाद सर्दी आएगी, फिर भी कवि शिकायत नहीं करता। वह वर्तमान का आनंद लेता है। हमें भी यही सीखना चाहिए कि बदलाव जीवन का हिस्सा है और हर अवस्था में सुंदरता और संतोष खोजना चाहिए।"),
C("✍️","भावार्थ लिखने के लिए सुझाव",["पद का मुख्य विचार","मानवीकरण का उदाहरण","एक बिंब","अंत में निष्कर्ष"],"भावार्थ लिखते समय सीधे कविता के शब्द मत दोहराइए, अपनी भाषा में समझाइए। पहले पद का मुख्य विचार एक-दो वाक्य में लिखिए। फिर किसी अलंकार, जैसे मानवीकरण, का एक उदाहरण दीजिए। एक सुंदर बिंब का ज़िक्र कीजिए और अंत में अपने शब्दों में निष्कर्ष लिखिए कि कवि ने शरद को पूर्णता और संतोष की ऋतु के रूप में दिखाया है। इस तरह उत्तर अच्छा और पूरे अंक वाला बनेगा।"),
],7)
